from __future__ import annotations

COMMAND_CENTER_HTML = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Advanced AI Trader — Research Command Center</title>
<script src="https://cdn.plot.ly/plotly-2.35.2.min.js"></script>
<style>
:root{--bg:#070b12;--panel:#0d1420;--line:#1c2a3b;--text:#e8eef7;--muted:#8291a7;--accent:#72e0ff;--good:#62e6a5;--warn:#ffd166;--bad:#ff6b81;--shadow:0 18px 50px rgba(0,0,0,.28)}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% -10%,#16314a 0,#070b12 42%);color:var(--text);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
button{font:inherit}.shell{max-width:1800px;margin:auto;padding:18px}.top{display:flex;align-items:center;justify-content:space-between;gap:18px;margin-bottom:16px}.brand{display:flex;align-items:center;gap:12px}.logo{width:42px;height:42px;border:1px solid #29435d;border-radius:12px;display:grid;place-items:center;background:#0c1825;color:var(--accent);font-weight:800;box-shadow:inset 0 0 20px #10263a}.title{font-size:20px;font-weight:750}.sub{color:var(--muted);font-size:12px}.badges{display:flex;gap:8px;flex-wrap:wrap}.badge{border:1px solid var(--line);background:#0b111b;border-radius:999px;padding:7px 11px;color:var(--muted)}.badge.live{color:var(--good);border-color:#23523f}.badge.research{color:var(--accent);border-color:#23506b}.grid{display:grid;grid-template-columns:1.6fr 1fr 1fr;gap:14px}.panel{background:linear-gradient(145deg,rgba(17,27,41,.96),rgba(9,15,24,.96));border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow);overflow:hidden}.panel h2{font-size:13px;margin:0;padding:13px 15px;border-bottom:1px solid var(--line);letter-spacing:.02em}.panel .body{padding:14px}.hero{grid-column:span 2;min-height:520px}.side{min-height:520px}.graph{height:465px}.controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.btn{border:1px solid #2b4258;background:#101d2b;color:var(--text);padding:8px 12px;border-radius:9px;cursor:pointer}.btn:hover{border-color:var(--accent)}.btn.stop{border-color:#623342;color:#ff9bab}.status{display:flex;align-items:center;gap:8px}.dot{width:8px;height:8px;border-radius:50%;background:var(--good);box-shadow:0 0 12px currentColor}.metrics{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.metric{padding:11px;border:1px solid var(--line);border-radius:10px;background:#0b121d}.metric .k{color:var(--muted);font-size:11px}.metric .v{font-size:18px;font-weight:700;margin-top:3px}.progress{height:7px;background:#09111b;border-radius:99px;overflow:hidden;border:1px solid var(--line)}.progress i{display:block;height:100%;background:linear-gradient(90deg,#4cc8ff,#7af0b2);width:0;transition:width .35s}.row{display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px solid #172231}.row:last-child{border-bottom:0}.muted{color:var(--muted)}.good{color:var(--good)}.warn{color:var(--warn)}.bad{color:var(--bad)}.table{width:100%;border-collapse:collapse;font-size:12px}.table th{text-align:left;color:var(--muted);font-weight:500;padding:7px;border-bottom:1px solid var(--line)}.table td{padding:8px 7px;border-bottom:1px solid #152131}.scroll{max-height:245px;overflow:auto}.agent{display:flex;justify-content:space-between;align-items:center;padding:9px 0;border-bottom:1px solid #172231}.agent:last-child{border-bottom:0}.agent b{font-size:12px}.pill{padding:3px 7px;border-radius:99px;background:#0a1d18;color:var(--good);font-size:10px;border:1px solid #214a3b}.events{display:flex;flex-direction:column;gap:8px}.event{padding:9px;border:1px solid var(--line);border-radius:9px;background:#0a111b}.event .time{font-size:10px;color:var(--muted)}.event .msg{font-size:12px;margin-top:2px}.wide{grid-column:span 3}.relationship{height:260px;position:relative;background:radial-gradient(circle at 50% 50%,#132335 0,#09111b 58%)}.nodes{position:absolute;inset:18px}.node{position:absolute;padding:8px 10px;border:1px solid #31516b;background:#0d1b29;border-radius:10px;font-size:11px;box-shadow:0 8px 22px #0006}.n1{left:5%;top:42%}.n2{left:25%;top:18%}.n3{left:25%;top:65%}.n4{left:48%;top:40%}.n5{left:68%;top:17%}.n6{left:68%;top:66%}.n7{right:4%;top:41%;color:var(--good)}svg{position:absolute;inset:0;width:100%;height:100%}line{stroke:#29445c;stroke-width:1.2}.footer{color:var(--muted);font-size:11px;padding:12px 2px}.note{padding:10px;border:1px dashed #2a4055;border-radius:9px;color:var(--muted);font-size:11px;margin-top:10px}
@media(max-width:1100px){.grid{grid-template-columns:1fr 1fr}.hero,.wide{grid-column:span 2}}@media(max-width:720px){.grid{grid-template-columns:1fr}.hero,.wide{grid-column:span 1}.top{align-items:flex-start;flex-direction:column}.hero{min-height:480px}.graph{height:420px}}
</style>
</head>
<body><div class="shell">
<header class="top"><div class="brand"><div class="logo">AI</div><div><div class="title">Advanced AI Trader · Research Command Center</div><div class="sub">Scientific training observability · isolated from live execution</div></div></div><div class="badges"><span class="badge research">● RESEARCH</span><span class="badge live">● GUARDIAN ENABLED</span><span class="badge">LIVE EXECUTION DISABLED</span></div></header>
<div class="grid">
<section class="panel hero"><h2>Penultimate representation · 3D latent space</h2><div class="body"><div class="controls"><div class="status"><span class="dot"></span><span id="statusText">Connecting…</span></div><span style="flex:1"></span><button class="btn" onclick="control('start')">Start</button><button class="btn stop" onclick="control('stop')">Stop</button></div><div style="height:10px"></div><div class="progress"><i id="bar"></i></div><div id="graph" class="graph"></div></div></section>
<section class="panel side"><h2>Training control & model metrics</h2><div class="body"><div class="metrics"><div class="metric"><div class="k">Experiment</div><div class="v" id="experiment">—</div></div><div class="metric"><div class="k">Epoch</div><div class="v" id="epoch">—</div></div><div class="metric"><div class="k">Validation loss</div><div class="v" id="loss">—</div></div><div class="metric"><div class="k">Samples processed</div><div class="v" id="samples">—</div></div></div><div class="note" id="datasetNote">Benchmark telemetry only. This current research loop is not crypto-market training.</div><div style="margin-top:12px"><div class="row"><span class="muted">Stage</span><b id="stage">—</b></div><div class="row"><span class="muted">Model</span><b id="model">—</b></div><div class="row"><span class="muted">Latent points</span><b id="points">—</b></div><div class="row"><span class="muted">Heartbeat</span><b id="heartbeat">—</b></div></div></div></section>
<section class="panel"><h2>Guardian status</h2><div class="body"><div class="row"><span>Policy</span><b class="good">guardian-v1</b></div><div class="row"><span>Live execution</span><b class="warn">Disabled</b></div><div class="row"><span>Uncertainty gate</span><b>0.80</b></div><div class="row"><span>Emergency stop</span><b class="good">Armed</b></div><div class="row"><span>Trading mode</span><b>Research</b></div><div class="note">The research UI can start/stop the benchmark supervisor only. It cannot sign or submit blockchain transactions.</div></div></section>
<section class="panel"><h2>AI research agents</h2><div class="body" id="agents"></div></section>
<section class="panel"><h2>Resource usage</h2><div class="body"><div class="row"><span>Process CPU time</span><b id="cpu">—</b></div><div class="row"><span>Process RSS</span><b id="rss">—</b></div><div class="row"><span>System load</span><b id="load">—</b></div><div class="row"><span>Worker state</span><b id="worker">—</b></div><div class="note">Resource telemetry is read-only and bounded. The dashboard does not allocate extra model compute.</div></div></section>
<section class="panel"><h2>Experiment history</h2><div class="body scroll"><table class="table"><thead><tr><th>Experiment</th><th>Status</th><th>Loss</th><th>Epochs</th></tr></thead><tbody id="history"></tbody></table></div></section>
<section class="panel wide"><h2>Feature → hypothesis → model → outcome relationships</h2><div class="body"><div class="relationship"><svg viewBox="0 0 1000 260" preserveAspectRatio="none"><line x1="95" y1="130" x2="280" y2="75"/><line x1="95" y1="130" x2="280" y2="185"/><line x1="350" y1="75" x2="520" y2="130"/><line x1="350" y1="185" x2="520" y2="130"/><line x1="590" y1="130" x2="705" y2="75"/><line x1="590" y1="130" x2="705" y2="185"/><line x1="775" y1="75" x2="920" y2="130"/><line x1="775" y1="185" x2="920" y2="130"/></svg><div class="nodes"><div class="node n1">Market features</div><div class="node n2">Momentum / state</div><div class="node n3">Volatility / liquidity</div><div class="node n4">Research hypothesis</div><div class="node n5">Model candidate</div><div class="node n6">Adversarial test</div><div class="node n7">Outcome / evidence</div></div></div></div></section>
<section class="panel wide"><h2>Live research event stream</h2><div class="body"><div class="events" id="events"></div></div></section>
</div><div class="footer">Research Command Center · local-first · benchmark-only training · visual telemetry is downstream/read-only · refresh interval 2s</div>
</div>
<script>
const $=id=>document.getElementById(id);
function fmt(v){return v===null||v===undefined?'—':(typeof v==='number'?v.toLocaleString(undefined,{maximumFractionDigits:6}):v)}
async function getJSON(path){const r=await fetch(path,{cache:'no-store'});if(!r.ok)throw new Error(r.status);return r.json()}
async function control(action){try{await fetch('/api/v1/research/control?action='+encodeURIComponent(action),{method:'POST'});await refresh()}catch(e){console.error(e)}}
function draw(points){const traces={};for(const p of points){const key=p.predicted_class||'UNKNOWN';(traces[key]??=[]).push(p)}const data=Object.entries(traces).map(([name,a])=>({name,x:a.map(p=>p.x),y:a.map(p=>p.y),z:a.map(p=>p.z),mode:'markers',type:'scatter3d',text:a.map(p=>`epoch=${p.epoch}<br>pred=${p.predicted_class}<br>true=${p.true_label}<br>return=${Number(p.pnl_or_return).toFixed(4)}`),hoverinfo:'text',marker:{size:4}}));Plotly.react('graph',data,{paper_bgcolor:'rgba(0,0,0,0)',plot_bgcolor:'rgba(0,0,0,0)',font:{color:'#9aa9bb'},margin:{l:0,r:0,t:10,b:0},showlegend:true,legend:{orientation:'h'},scene:{bgcolor:'rgba(0,0,0,0)',xaxis:{title:'PC1',gridcolor:'#1b2a3a',zerolinecolor:'#263b50'},yaxis:{title:'PC2',gridcolor:'#1b2a3a',zerolinecolor:'#263b50'},zaxis:{title:'PC3',gridcolor:'#1b2a3a',zerolinecolor:'#263b50'}}},{responsive:true,displaylogo:false});}
function renderAgents(a){$('agents').innerHTML=a.map(x=>`<div class="agent"><div><b>${x.name}</b><div class="muted">${x.role}</div></div><span class="pill">${x.status}</span></div>`).join('')}
function renderHistory(h){$('history').innerHTML=h.length?h.map(x=>`<tr><td>${x.experiment_id}</td><td class="good">${x.status}</td><td>${fmt(x.validation_loss)}</td><td>${x.epochs}</td></tr>`).join(''):`<tr><td colspan="4" class="muted">No completed experiments yet.</td></tr>`}
function renderEvents(e){$('events').innerHTML=e.length?e.slice(0,16).map(x=>`<div class="event"><div class="time">${x.timestamp} · ${x.type}</div><div class="msg">${x.message}</div></div>`).join(''):`<div class="muted">Waiting for research events…</div>`}
async function refresh(){try{const [s,l,h,e,r,a]=await Promise.all([getJSON('/api/v1/research/status'),getJSON('/api/v1/research/latent'),getJSON('/api/v1/research/history'),getJSON('/api/v1/research/events'),getJSON('/api/v1/research/resources'),getJSON('/api/v1/research/agents')]);$('statusText').textContent=`${s.status.toUpperCase()} · ${s.stage}`;$('bar').style.width=`${s.progress||0}%`;$('experiment').textContent=s.experiment_id||'—';$('epoch').textContent=`${s.epoch||0}/${s.epochs||0}`;$('loss').textContent=fmt(s.validation_loss);$('samples').textContent=fmt(s.samples_processed);$('stage').textContent=s.stage;$('model').textContent=s.model_id||'—';$('points').textContent=fmt(l.count);$('heartbeat').textContent=s.heartbeat_at||'—';$('datasetNote').textContent=s.market_training?'Market training enabled.':'Benchmark telemetry only. This current research loop is not crypto-market training.';$('cpu').textContent=fmt(r.cpu_seconds_since_start)+' s';$('rss').textContent=fmt(r.rss_mb)+' MB';$('load').textContent=fmt(r.load_1m);$('worker').textContent=r.worker;draw(l.points);renderHistory(h);renderEvents(e);renderAgents(a)}catch(err){$('statusText').textContent='Telemetry unavailable';console.error(err)}}
renderAgents([{name:'Researcher',role:'experiment orchestration',status:'ready'},{name:'Math Scientist',role:'hypothesis / objective critique',status:'ready'},{name:'Feature Scientist',role:'feature quality / leakage review',status:'ready'},{name:'Model Builder',role:'candidate architecture lab',status:'ready'},{name:'Adversarial Critic',role:'stress and failure analysis',status:'ready'},{name:'Evaluator',role:'out-of-sample evidence',status:'ready'}]);refresh();setInterval(refresh,2000);
</script></body></html>"""
